@Test
public void testReportAPIs() {
    OzoneConfiguration conf = new OzoneConfiguration();
    DatanodeStateMachine datanodeStateMachineMock = mock(DatanodeStateMachine.class);
    StateContext stateContext = new StateContext(conf, DatanodeStates.getInitState(), datanodeStateMachineMock);
    InetSocketAddress scm1 = new InetSocketAddress("scm1", 9001);
    InetSocketAddress scm2 = new InetSocketAddress("scm2", 9001);
    // Try to add report with endpoint. Should not be stored.
    stateContext.addReport(mock(GeneratedMessage.class));
    assertTrue(stateContext.getAllAvailableReports(scm1).isEmpty());
    // Add 2 scm endpoints.
    stateContext.addEndpoint(scm1);
    stateContext.addEndpoint(scm2);
    // Add report. Should be added to all endpoints.
    stateContext.addReport(mock(GeneratedMessage.class));
    List<GeneratedMessage> allAvailableReports = stateContext.getAllAvailableReports(scm1);
    assertEquals(1, allAvailableReports.size());
    assertEquals(1, stateContext.getAllAvailableReports(scm2).size());
    // Assert the reports are no longer available.
    assertTrue(stateContext.getAllAvailableReports(scm1).isEmpty());
    // Put back reports.
    stateContext.putBackReports(allAvailableReports, scm1);
    assertFalse(stateContext.getAllAvailableReports(scm1).isEmpty());
}

@Test
public void testActionAPIs() {
    OzoneConfiguration conf = new OzoneConfiguration();
    DatanodeStateMachine datanodeStateMachineMock = mock(DatanodeStateMachine.class);
    StateContext stateContext = new StateContext(conf, DatanodeStates.getInitState(), datanodeStateMachineMock);
    InetSocketAddress scm1 = new InetSocketAddress("scm1", 9001);
    InetSocketAddress scm2 = new InetSocketAddress("scm2", 9001);
    // Try to get containerActions for endpoint which is not yet added.
    List<ContainerAction> containerActions = stateContext.getPendingContainerAction(scm1, 10);
    assertTrue(containerActions.isEmpty());
    // Try to get pipelineActions for endpoint which is not yet added.
    List<PipelineAction> pipelineActions = stateContext.getPendingPipelineAction(scm1, 10);
    assertTrue(pipelineActions.isEmpty());
    // Add 2 scm endpoints.
    stateContext.addEndpoint(scm1);
    stateContext.addEndpoint(scm2);
    // Add PipelineAction. Should be added to all endpoints.
    stateContext.addPipelineActionIfAbsent(PipelineAction.newBuilder().setAction(PipelineAction.Action.CLOSE).build());
    pipelineActions = stateContext.getPendingPipelineAction(scm1, 10);
    assertEquals(1, pipelineActions.size());
    // Add ContainerAction. Should be added to all endpoints.
    stateContext.addContainerAction(ContainerAction.newBuilder().setAction(CLOSE).setContainerID(100L).build());
    containerActions = stateContext.getPendingContainerAction(scm2, 10);
    assertEquals(1, containerActions.size());
}

@Test
public void testAwait() throws InterruptedException {
    SCMConnectionManager connectionManager = Mockito.mock(SCMConnectionManager.class);
    List<EndpointStateMachine> stateMachines = new ArrayList<>();
    when(connectionManager.getValues()).thenReturn(stateMachines);
    RunningDatanodeState state = new RunningDatanodeState(null, connectionManager, null);
    int threadPoolSize = 2;
    ExecutorService executorService = Executors.newFixedThreadPool(threadPoolSize);
    ExecutorCompletionService ecs = new ExecutorCompletionService<>(executorService);
    state.setExecutorCompletionService(ecs);
    for (int i = 0; i < threadPoolSize; i++) {
        stateMachines.add(new EndpointStateMachine(null, null, null));
    }
    CompletableFuture<EndpointStateMachine.EndPointStates> futureOne = new CompletableFuture<>();
    for (int i = 0; i < threadPoolSize; i++) {
        ecs.submit(() -> futureOne.get());
    }
    long startTime = Time.monotonicNow();
    state.await(500, TimeUnit.MILLISECONDS);
    long endTime = Time.monotonicNow();
    Assert.assertTrue((endTime - startTime) >= 500);
    futureOne.complete(SHUTDOWN);
    CompletableFuture<EndpointStateMachine.EndPointStates> futureTwo = new CompletableFuture<>();
    for (int i = 0; i < threadPoolSize; i++) {
        ecs.submit(() -> futureTwo.get());
    }
    futureTwo.complete(SHUTDOWN);
    startTime = Time.monotonicNow();
    state.await(500, TimeUnit.MILLISECONDS);
    endTime = Time.monotonicNow();
    Assert.assertTrue((endTime - startTime) < 500);
    executorService.shutdown();
}

