/**
 * Test that Handler handles different command types correctly.
 */
public void testHandlerCommandHandling() throws Exception {
    Mockito.reset(handler);
    // Test Create Container Request handling
    ContainerCommandRequestProto createContainerRequest = ContainerProtos.ContainerCommandRequestProto.newBuilder().setCmdType(ContainerProtos.Type.CreateContainer).setContainerID(DUMMY_CONTAINER_ID).setDatanodeUuid(DATANODE_UUID).setCreateContainer(ContainerProtos.CreateContainerRequestProto.getDefaultInstance()).build();
    KeyValueContainer container = Mockito.mock(KeyValueContainer.class);
    DispatcherContext context = new DispatcherContext.Builder().build();
    KeyValueHandler.dispatchRequest(handler, createContainerRequest, container, context);
    Mockito.verify(handler, times(1)).handleCreateContainer(any(ContainerCommandRequestProto.class), any());
    // Test Read Container Request handling
    ContainerCommandRequestProto readContainerRequest = getDummyCommandRequestProto(ContainerProtos.Type.ReadContainer);
    KeyValueHandler.dispatchRequest(handler, readContainerRequest, container, context);
    Mockito.verify(handler, times(1)).handleReadContainer(any(ContainerCommandRequestProto.class), any());
    // Test Update Container Request handling
    ContainerCommandRequestProto updateContainerRequest = getDummyCommandRequestProto(ContainerProtos.Type.UpdateContainer);
    KeyValueHandler.dispatchRequest(handler, updateContainerRequest, container, context);
    Mockito.verify(handler, times(1)).handleUpdateContainer(any(ContainerCommandRequestProto.class), any());
    // Test Delete Container Request handling
    ContainerCommandRequestProto deleteContainerRequest = getDummyCommandRequestProto(ContainerProtos.Type.DeleteContainer);
    KeyValueHandler.dispatchRequest(handler, deleteContainerRequest, container, context);
    Mockito.verify(handler, times(1)).handleDeleteContainer(any(ContainerCommandRequestProto.class), any());
    // Test List Container Request handling
    ContainerCommandRequestProto listContainerRequest = getDummyCommandRequestProto(ContainerProtos.Type.ListContainer);
    KeyValueHandler.dispatchRequest(handler, listContainerRequest, container, context);
    Mockito.verify(handler, times(1)).handleUnsupportedOp(any(ContainerCommandRequestProto.class));
    // Test Close Container Request handling
    ContainerCommandRequestProto closeContainerRequest = getDummyCommandRequestProto(ContainerProtos.Type.CloseContainer);
    KeyValueHandler.dispatchRequest(handler, closeContainerRequest, container, context);
    Mockito.verify(handler, times(1)).handleCloseContainer(any(ContainerCommandRequestProto.class), any());
    // Test Put Block Request handling
    ContainerCommandRequestProto putBlockRequest = getDummyCommandRequestProto(ContainerProtos.Type.PutBlock);
    KeyValueHandler.dispatchRequest(handler, putBlockRequest, container, context);
    Mockito.verify(handler, times(1)).handlePutBlock(any(ContainerCommandRequestProto.class), any(), any());
    // Test Get Block Request handling
    ContainerCommandRequestProto getBlockRequest = getDummyCommandRequestProto(ContainerProtos.Type.GetBlock);
    KeyValueHandler.dispatchRequest(handler, getBlockRequest, container, context);
    Mockito.verify(handler, times(1)).handleGetBlock(any(ContainerCommandRequestProto.class), any());
    // Test Delete Block Request handling
    ContainerCommandRequestProto deleteBlockRequest = getDummyCommandRequestProto(ContainerProtos.Type.DeleteBlock);
    KeyValueHandler.dispatchRequest(handler, deleteBlockRequest, container, context);
    Mockito.verify(handler, times(1)).handleDeleteBlock(any(ContainerCommandRequestProto.class), any());
    // Test List Block Request handling
    ContainerCommandRequestProto listBlockRequest = getDummyCommandRequestProto(ContainerProtos.Type.ListBlock);
    KeyValueHandler.dispatchRequest(handler, listBlockRequest, container, context);
    Mockito.verify(handler, times(2)).handleUnsupportedOp(any(ContainerCommandRequestProto.class));
    // Test Read Chunk Request handling
    ContainerCommandRequestProto readChunkRequest = getDummyCommandRequestProto(ContainerProtos.Type.ReadChunk);
    KeyValueHandler.dispatchRequest(handler, readChunkRequest, container, context);
    Mockito.verify(handler, times(1)).handleReadChunk(any(ContainerCommandRequestProto.class), any(), any());
    // Test Delete Chunk Request handling
    ContainerCommandRequestProto deleteChunkRequest = getDummyCommandRequestProto(ContainerProtos.Type.DeleteChunk);
    KeyValueHandler.dispatchRequest(handler, deleteChunkRequest, container, context);
    Mockito.verify(handler, times(1)).handleDeleteChunk(any(ContainerCommandRequestProto.class), any());
    // Test Write Chunk Request handling
