@Test
public void testDownloadAndImportReplicatorFailure() {
    ReplicationSupervisor supervisor = new ReplicationSupervisor(set, mutableReplicator, newDirectExecutorService());
    // Mock to fetch an exception in the importContainer method.
    SimpleContainerDownloader moc = Mockito.mock(SimpleContainerDownloader.class);
    CompletableFuture<Path> res = new CompletableFuture<>();
    res.complete(Paths.get("file:/tmp/no-such-file"));
    Mockito.when(moc.getContainerDataFromReplicas(Mockito.anyLong(), Mockito.anyList())).thenReturn(res);
    ContainerReplicator replicatorFactory = new DownloadAndImportReplicator(set, null, moc, null);
    replicatorRef.set(replicatorFactory);
    GenericTestUtils.LogCapturer logCapturer = GenericTestUtils.LogCapturer.captureLogs(DownloadAndImportReplicator.LOG);
    supervisor.addTask(new ReplicationTask(1L, emptyList()));
    Assert.assertEquals(1, supervisor.getReplicationFailureCount());
    Assert.assertEquals(0, supervisor.getReplicationSuccessCount());
    Assert.assertTrue(logCapturer.getOutput().contains("Container 1 replication was unsuccessful."));
}

