private void setupContainerManager() throws IOException {
    dnList.add(DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build());
    dnList.add(DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build());
    dnList.add(DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build());
    final ContainerInfo container = new ContainerInfo.Builder().setContainerID(1).setReplicationFactor(ReplicationFactor.THREE).setState(HddsProtos.LifeCycleState.CLOSED).build();
    final Set<ContainerReplica> replicaSet = dnList.stream().map(datanodeDetails -> ContainerReplica.newBuilder().setContainerID(container.containerID()).setContainerState(ContainerReplicaProto.State.OPEN).setDatanodeDetails(datanodeDetails).build()).collect(Collectors.toSet());
