private EndpointStateMachine registerTaskHelper(InetSocketAddress scmAddress, int rpcTimeout, boolean clearDatanodeDetails) throws Exception {
    OzoneConfiguration conf = SCMTestUtils.getConf();
    EndpointStateMachine rpcEndPoint = createEndpoint(conf, scmAddress, rpcTimeout);
    rpcEndPoint.setState(EndpointStateMachine.EndPointStates.REGISTER);
    OzoneContainer ozoneContainer = mock(OzoneContainer.class);
    when(ozoneContainer.getNodeReport()).thenReturn(TestUtils.createNodeReport(getStorageReports(UUID.randomUUID())));
    ContainerController controller = Mockito.mock(ContainerController.class);
    when(controller.getContainerReport()).thenReturn(TestUtils.getRandomContainerReports(10));
    when(ozoneContainer.getController()).thenReturn(controller);
    when(ozoneContainer.getPipelineReport()).thenReturn(TestUtils.getRandomPipelineReports());
    DataNodeLayoutVersionManager versionManager = Mockito.mock(DataNodeLayoutVersionManager.class);
    when(versionManager.getMetadataLayoutVersion()).thenReturn(TEST_METADATA_LAYOUT_VERSION);
    when(versionManager.getSoftwareLayoutVersion()).thenReturn(TEST_SOFTWARE_LAYOUT_VERSION);
    RegisterEndpointTask endpointTask = new RegisterEndpointTask(rpcEndPoint, conf, ozoneContainer, mock(StateContext.class), versionManager);
    if (!clearDatanodeDetails) {
        DatanodeDetails datanodeDetails = randomDatanodeDetails();
        endpointTask.setDatanodeDetails(datanodeDetails);
    }
    endpointTask.call();
    return rpcEndPoint;
}

